#pragma once
// Factory groove table for the Practice plugin's drum machine.
//
// Patterns are written as one step-string per instrument lane rather than as
// arrays of {step, instrument, velocity} structs. The notation is the point:
// a groove you can read as a grid is a groove you can correct by eye, and the
// table is meant to be edited while listening rather than regenerated by a
// script. One character per step:
//
//   X  accent      (127)   the backbeat, the downbeat crash
//   x  normal      (104)
//   o  soft        ( 82)   hats under a busy part
//   -  ghost       ( 42)   snare ghost notes; audible as touch, not as a hit
//   .  rest
//
// Every lane string in a pattern must be exactly stepsPerBar * bars characters
// long; validatePatternTable() below asserts this, and the offline harness runs
// it so a mistyped groove fails the build rather than silently truncating.
#include <cstdint>
#include <cstring>

namespace hexdrums {

// Kit layout. Ordered so the GM-ish percussion mapping stays contiguous and the
// step grid in the web GUI can lay the lanes out top-to-bottom as a drummer
// would read them (cymbals high, kick low).
enum Instrument : uint8_t {
    INST_KICK = 0,
    INST_SNARE,
    INST_SIDESTICK,
    INST_TOM_HI,
    INST_TOM_MID,
    INST_TOM_FLOOR,
    INST_HAT_CLOSED,
    INST_HAT_PEDAL,
    INST_HAT_OPEN,
    INST_CRASH,
    INST_RIDE,
    INST_RIDE_BELL,
    INST_COUNT
};

inline const char* instrumentName(uint8_t i) noexcept {
    static const char* kNames[INST_COUNT] = {
        "Kick", "Snare", "Sidestick", "Tom Hi", "Tom Mid", "Tom Floor",
        "Hat Closed", "Hat Pedal", "Hat Open", "Crash", "Ride", "Ride Bell"
    };
    return (i < INST_COUNT) ? kNames[i] : "?";
}

// Velocity for one step character. Returns 0 for a rest.
inline uint8_t stepVelocity(char c) noexcept {
    switch (c) {
        case 'X': return 127;
        case 'x': return 104;
        case 'o': return 82;
        case '-': return 42;
        default:  return 0;     // '.' and anything else
    }
}

struct DrumLane {
    uint8_t     inst;
    const char* steps;
};

struct DrumPattern {
    const char*     name;
    uint8_t         stepsPerBar;   // 16 = sixteenths, 12 = triplet eighths
    uint8_t         bars;
    const DrumLane* lanes;
    uint8_t         numLanes;
};

// ── The grooves ──────────────────────────────────────────────────────────────
// Sixteenth-note grid unless noted. Positions:  1 e & a 2 e & a 3 e & a 4 e & a

namespace patterns {

// 1. The reference rock beat. Everything else is a deformation of this.
inline const DrumLane kRock8[] = {
    { INST_HAT_CLOSED, "x.o.x.o.x.o.x.o." },
    { INST_KICK,       "x.......x......." },
    { INST_SNARE,      "....X.......X..." },
};

// 2. Sixteenth hats: the same beat with the subdivision filled in.
inline const DrumLane kRock16[] = {
    { INST_HAT_CLOSED, "xoooxoooxoooxooo" },
    { INST_KICK,       "x.....x.x......." },
    { INST_SNARE,      "....X..-....X..-" },
};

// 3. Half-time. The backbeat moves to 3, which is what makes a riff feel twice
//    as slow without touching the tempo.
inline const DrumLane kHalfTime[] = {
    { INST_HAT_CLOSED, "x.o.x.o.x.o.x.o." },
    { INST_KICK,       "x.....x........." },
    { INST_SNARE,      "........X......." },
    { INST_CRASH,      "X..............." },
};

// 4. Sustained double kick under a standard backbeat.
inline const DrumLane kDoubleKick[] = {
    { INST_RIDE,       "x...x...x...x..." },
    { INST_KICK,       "xxxxxxxxxxxxxxxx" },
    { INST_SNARE,      "....X.......X..." },
    { INST_CRASH,      "X..............." },
};

// 5. Traditional blast: kick and snare alternate on consecutive eighths.
inline const DrumLane kBlast[] = {
    { INST_HAT_CLOSED, "x.x.x.x.x.x.x.x." },
    { INST_KICK,       "x.x.x.x.x.x.x.x." },
    { INST_SNARE,      ".x.x.x.x.x.x.x.x" },
};

// 6. Bomb blast: kick and snare land together. Denser, and the one that
//    actually disappears in a mix unless the kick click is up.
inline const DrumLane kBombBlast[] = {
    { INST_HAT_CLOSED, "x.x.x.x.x.x.x.x." },
    { INST_KICK,       "x.x.x.x.x.x.x.x." },
    { INST_SNARE,      "x.x.x.x.x.x.x.x." },
};

// 7. Thrash skank / two-beat.
inline const DrumLane kSkank[] = {
    { INST_HAT_CLOSED, "x.x.x.x.x.x.x.x." },
    { INST_KICK,       "x...x...x...x..." },
    { INST_SNARE,      "..X...X...X...X." },
};

// 8. Gallop — the kick figure that defines the NWOBHM rhythm guitar it sits under.
inline const DrumLane kGallop[] = {
    { INST_HAT_CLOSED, "x.x.x.x.x.x.x.x." },
    { INST_KICK,       "x.xxx.xxx.xxx.xx" },
    { INST_SNARE,      "....X.......X..." },
};

// 9. D-beat. The kick's displaced second hit is the whole identity of it.
inline const DrumLane kDBeat[] = {
    { INST_HAT_CLOSED, "x.x.x.x.x.x.x.x." },
    { INST_KICK,       "x..x..x.x..x..x." },
    { INST_SNARE,      "....X.......X..." },
};

// 10. Shuffle. Triplet eighths, so twelve steps to the bar.
inline const DrumLane kShuffle[] = {
    { INST_HAT_CLOSED, "x.xx.xx.xx.x" },
    { INST_KICK,       "x.....x....." },
    { INST_SNARE,      "...X.....X.." },
};

// 11. 6/8 feel, also on the triplet grid.
inline const DrumLane kSixEight[] = {
    { INST_HAT_CLOSED, "x.ox.ox.ox.o" },
    { INST_KICK,       "x.....x..x.." },
    { INST_SNARE,      "...X.....X.." },
};

// 12. Ride groove with the hat on the pedal — the practice default for working
//     out over changes without the hat masking everything.
inline const DrumLane kRideGroove[] = {
    { INST_RIDE,       "x.o.x.o.x.o.x.o." },
    { INST_HAT_PEDAL,  "....x.......x..." },
    { INST_KICK,       "x.....x.x......." },
    { INST_SNARE,      "....X.......X..." },
};

// 13. Floor-tom groove: no hats at all, which is what makes it read as tribal
//     rather than as a rock beat with the cymbals muted.
inline const DrumLane kTomGroove[] = {
    { INST_TOM_FLOOR,  "x.o.x.o.x.o.x.o." },
    { INST_KICK,       "x...x...x...x..." },
    { INST_SNARE,      "....X.......X..." },
};

// 14. Breakdown. Sparse on purpose — the space is the point.
inline const DrumLane kBreakdown[] = {
    { INST_CRASH,      "X.......X......." },
    { INST_KICK,       "x..x..x...x....." },
    { INST_SNARE,      "........X......." },
};

// 15. Open-hat driving eighths.
inline const DrumLane kOpenHat[] = {
    { INST_HAT_OPEN,   "x...x...x...x..." },
    { INST_HAT_CLOSED, "..x...x...x...x." },
    { INST_KICK,       "x.......x.x....." },
    { INST_SNARE,      "....X.......X..." },
};

// 16. Two-bar phrase: three bars' worth of groove answered by a tom fill. The
//     only multi-bar entry, and the one that proves the sequencer's bar
//     handling — a fill that lands a step early is immediately obvious.
inline const DrumLane kFillPhrase[] = {
    { INST_HAT_CLOSED, "x.o.x.o.x.o.x.o.x.o.x.o........." },
    { INST_KICK,       "x.......x.......x.......x......." },
    { INST_SNARE,      "....X.......X.......X...--x.x.x." },
    { INST_TOM_HI,     "........................x......." },
    { INST_TOM_MID,    "..........................x....." },
    { INST_TOM_FLOOR,  "............................x.x." },
    { INST_CRASH,      "X..............................." },
};

// 17. Metronome. Quarter notes on the sidestick with 1 accented — a click that
//     is a kit voice, so it sits in the same mix as everything else.
inline const DrumLane kMetronome[] = {
    { INST_SIDESTICK,  "Xxxx" },
};

} // namespace patterns

#define HEXDRUMS_PATTERN(nm, spb, br, lanes) \
    { nm, spb, br, lanes, static_cast<uint8_t>(sizeof(lanes) / sizeof(DrumLane)) }

inline const DrumPattern* patternTable(int& countOut) noexcept {
    static const DrumPattern kTable[] = {
        HEXDRUMS_PATTERN("Rock 8ths",    16, 1, patterns::kRock8),
        HEXDRUMS_PATTERN("Rock 16ths",   16, 1, patterns::kRock16),
        HEXDRUMS_PATTERN("Half-Time",    16, 1, patterns::kHalfTime),
        HEXDRUMS_PATTERN("Double Kick",  16, 1, patterns::kDoubleKick),
        HEXDRUMS_PATTERN("Blast",        16, 1, patterns::kBlast),
        HEXDRUMS_PATTERN("Bomb Blast",   16, 1, patterns::kBombBlast),
        HEXDRUMS_PATTERN("Thrash Skank", 16, 1, patterns::kSkank),
        HEXDRUMS_PATTERN("Gallop",       16, 1, patterns::kGallop),
        HEXDRUMS_PATTERN("D-Beat",       16, 1, patterns::kDBeat),
        HEXDRUMS_PATTERN("Shuffle",      12, 1, patterns::kShuffle),
        HEXDRUMS_PATTERN("6/8",          12, 1, patterns::kSixEight),
        HEXDRUMS_PATTERN("Ride Groove",  16, 1, patterns::kRideGroove),
        HEXDRUMS_PATTERN("Tom Groove",   16, 1, patterns::kTomGroove),
        HEXDRUMS_PATTERN("Breakdown",    16, 1, patterns::kBreakdown),
        HEXDRUMS_PATTERN("Open Hat",     16, 1, patterns::kOpenHat),
        HEXDRUMS_PATTERN("Fill Phrase",  16, 2, patterns::kFillPhrase),
        HEXDRUMS_PATTERN("Metronome",     4, 1, patterns::kMetronome),
    };
    countOut = static_cast<int>(sizeof(kTable) / sizeof(DrumPattern));
    return kTable;
}

#undef HEXDRUMS_PATTERN

// Every lane must span the pattern exactly. Called by the offline harness; a
// mistyped groove would otherwise read past the end of a short string or
// silently ignore the tail of a long one.
inline bool validatePatternTable(const char** failName, int* failLane) noexcept {
    int n = 0;
    const DrumPattern* t = patternTable(n);
    for (int p = 0; p < n; ++p) {
        const size_t want = static_cast<size_t>(t[p].stepsPerBar) * t[p].bars;
        for (int l = 0; l < t[p].numLanes; ++l) {
            if (std::strlen(t[p].lanes[l].steps) != want) {
                if (failName) *failName = t[p].name;
                if (failLane) *failLane = l;
                return false;
            }
        }
    }
    return true;
}

} // namespace hexdrums
